function countDate(stock){if(!stock?.countedAt&&!stock?.date&&!stock?.countDate)return "No count recorded";const value=stock.countedAt||stock.date||stock.countDate;const time=stock.precision||stock.countedAtPrecision;const hasTime=String(value).includes('T')&&time!=='date'&&time!=='day';const deviceTime=hasTime&&Number.isInteger(stock.countOffsetMinutes);const formatted=new Intl.DateTimeFormat("en-US",{timeZone:deviceTime?'UTC':'America/New_York',day:'2-digit',month:'2-digit',year:'numeric',...(hasTime?{hour:'2-digit',minute:'2-digit'}:{})}).format(new Date(new Date(value.includes('T')?value:value+'T12:00:00-04:00').getTime()-(deviceTime?stock.countOffsetMinutes*60000:0)));const moment={before:"before opening",before_opening:"before opening",during:"during business hours",after:"after closing",after_closing:"after closing",'Antes da abertura':"before opening",'Durante a operação':"during business hours",'Após o fechamento':"after closing"}[stock.moment];return `${formatted}${moment?' · '+moment:''}`;}
function countQuantity(stock){const qty=stock.qty??stock.knownSubtotal;return qty==null?"No count":`${preciseNumber(qty)} ${e(stock.uom||'')}`;}
function countDetail(stock){return `<section class="last-count"><div class="section-title">Last inventory count</div><div class="detail-grid">${pair(stock.qty==null&&stock.knownSubtotal!=null?"Total of available counts":"Counted quantity",countQuantity(stock))}${pair("Last count date",e(countDate(stock)))}</div>${stock.source==='no_completed_count'?"<p class=\"count-source\">No count has been recorded for this location.</p>":stock.local?"<p class=\"count-source\">Count saved in this local preview.</p>":"<p class=\"count-source\">Count saved to the database. Later inventory activity is not included.</p>"}${(stock.warnings||[]).map(w=>notice(e(w),true)).join('')}${stock.areas?.length?`<div class="table-wrap"><table><thead><tr><th>STORAGE AREA</th><th>COUNT</th><th>DATE</th></tr></thead><tbody>${stock.areas.map(a=>`<tr><td>${e(a.areaName||a.storageAreaName||a.name||"No area")}</td><td>${a.qty==null?"No count":`${preciseNumber(a.qty)} ${e(a.uom||stock.uom||'')}`} </td><td>${e(countDate(a))}</td></tr>`).join('')}</tbody></table></div>`:''}</section>`;}

