function salesChart(){
  const p=selectedSalesPeriod(),locs=data.locations.filter(x=>state.store==='all'||x.id===state.store),vals=p.dates.map(d=>locs.map(l=>p.current.find(x=>x.date===d&&x.locationId===l.id)?.netSales||0));
  const min=Math.min(...vals.flat(),0),max=Math.max(...vals.flat(),0),span=max-min||1,lo=min<0?min-span*.12:0,hi=max>0?max+span*.18:span*.12;
  const W=700,H=220,left=48,right=16,width=(W-left-right)/Math.max(vals.length,1),bw=Math.min(23,width/(locs.length+1)),yFor=v=>24+(hi-v)/(hi-lo)*161,base=yFor(0);
  let svg='';for(let n=0;n<4;n++){const value=lo+(hi-lo)*n/3,y=yFor(value),label=Math.abs(value)>=1000?`$${number(value/1000)}k`:`$${number(value)}`;svg+=`<line x1="${left}" y1="${y}" x2="686" y2="${y}" stroke="#394131" stroke-dasharray="3 5"/><text x="5" y="${y+3}" fill="#a8b29d" font-size="9">${label}</text>`;}
  if(min<0)svg+=`<line x1="${left}" y1="${base}" x2="686" y2="${base}" stroke="#86927c"/>`;
  vals.forEach((group,i)=>{group.forEach((v,j)=>{const height=Math.abs(yFor(v)-base),x=left+i*width+width/2+(j-(locs.length-1)/2)*(bw+4)-bw/2;svg+=`<rect tabindex="0" aria-label="${e(locs[j].name)}, ${date(p.dates[i])}, ${money(v)}" class="chart-bar" x="${x}" y="${Math.min(base,yFor(v))}" width="${bw}" height="${height}" rx="3" fill="${v<0?'#d88d79':locs[j].name.includes('Sherwood')?'#fece07':'#94a382'}"><title>${e(locs[j].name)} • ${date(p.dates[i])}: ${money(v)}</title></rect>`;});if(i%Math.max(1,Math.ceil(vals.length/7))===0)svg+=`<text x="${left+i*width+width/2}" y="207" text-anchor="middle" fill="#a8b29d" font-size="9">${date(p.dates[i]).replace(" of ",' ')}</text>`;});
  return `<section class="panel chart-panel"><div class="panel-head"><div><h2>Your business at a glance</h2><p>Sales by day and location</p></div><span class="chart-period">${p.dates.length?`${date(p.dates[0])} — ${date(p.dates.at(-1))}`:"No sales in this date range"}</span></div><div class="legend"><span><b></b>Sherwood Plaza</span><span><b class="mall"></b>Natick Mall</span>${min<0?"<span><b style=\"background:#d88d79\"></b>Negative adjustments</span>":''}</div><svg class="sales-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Net sales by location">${svg}</svg><div class="chart-bottom"><span>Source: imported Square sales</span><strong>${money(p.total)} in this date range</strong></div></section>`;
}
function staffOverview(){return heading("Operations center","Overview","View your assigned locations and record inventory counts.",btn("New count",'new-count','clipboard-list','primary'))+`<div class="stats">${stat("Catalog items",number(unique(currentItems()).length),'package',"Active at selected locations")}${stat("Prep items",number(scopedPreparations().length),'cooking-pot',"Production kitchen")}${stat("Open transfers",number(records('transfers').filter(storeMatch).filter(x=>!['completed','cancelled'].includes(x.status)).length),'arrow-left-right',"Internal shipments")}</div><section class="panel"><div class="panel-head"><h2>Your workspace</h2></div>${attention('boxes','Inventory','View stock and inventory history','inventory')}${attention('cooking-pot','Prep','View usage and production history','preparation')}${attention('arrow-left-right','Transfers','View internal shipments','transfers')}${attention('notebook-tabs','Recipes','View recipes and instructions','recipes')}</section>`;}
function overview(){if(isStaff(session?.role))return staffOverview();const p=selectedSalesPeriod(),orders=records('orders').filter(storeMatch),pending=orders.filter(x=>x.status==='ordered'),drafts=data.recipes.filter(x=>x.status==='draft');return heading("Operations center","Overview","A connected view of your two locations.",periodControl()+btn("New activity",'quick','plus','primary'))+periodNotice(p)+`<div class="stats">${stat("Net sales",money(p.total),'dollar-sign',"vs. previous period",p.growth)}${stat("Items sold",number(p.quantity),'shopping-basket',state.dateRange?"In the selected date range":`${p.dates.length} days of imported sales`)}${stat("Catalog items",number(unique(currentItems()).length),'package',"Active at selected locations")}${stat("Orders placed",pending.length,'truck',"Status saved in the database")}</div><div class="dashboard-grid">${salesChart()}<section class="panel attention-panel"><div class="panel-head"><div><h2>Needs your attention</h2><p>Your next steps</p></div>${icon('sparkles')}</div><div class="attention-total"><strong>${data.meta.pendingImportRows??"Calculating…"}</strong><span>sales lines need review<br>across both locations</span></div>${attention('git-branch',"Review sales mappings","Modifiers and recipe versions",'sales-issues')}${attention('notebook-pen',`${drafts.length} draft ${drafts.length===1?'recipe':'recipes'}`,"Review versions before publishing",'recipes-drafts','red')}${attention('package-check',`${pending.length} ${pending.length===1?'order':'orders'} with a status to review`,"Status and receipts in history",'purchases','green')}<div class="attention-foot">${icon('shield-check')}Review before updating inventory</div></section></div><div class="operations-grid"><section class="panel"><div class="panel-head"><div><h2>Purchasing activity</h2><p>Latest orders for selected locations</p></div>${btn("View all",'purchases','arrow-up-right','ghost sm')}</div>${orderTable(orders.slice(0,4))}</section><section class="panel"><div class="panel-head"><div><h2>From the kitchen to the store</h2><p>Prep and internal transfers</p></div>${icon('arrow-up-right')}</div><div class="route-card"><div class="route-vis"><span class="store-node">${icon('cooking-pot')}</span><div class="route-line"><span>TUE & FRI</span></div><span class="store-node">${icon('store')}</span></div><div class="route-labels"><div>Sherwood Plaza<small>Production and shipping</small></div><div>Natick Mall<small>Review and receiving</small></div></div><div class="route-stats"><div><strong>${scopedPreparations().length}</strong><span>prep items</span></div><div><strong>${records('transfers').filter(x=>!['completed','cancelled'].includes(x.status)).length}</strong><span>open shipments</span></div></div><p class="route-note"><strong>Tuesday:</strong> covers Wednesday through Friday.<br><strong>Friday:</strong> covers Saturday through Tuesday.</p>${btn("Create transfer",'new-transfer','plus')}</div></section></div>`;}
function attention(ic,title,text,action,color=''){return `<div class="attention-item" role="button" tabindex="0" data-action="${action}"><span class="attention-icon ${color}">${icon(ic)}</span><div><strong>${title}</strong><p>${text}</p></div>${icon('chevron-right')}</div>`;}
function searchToolbar(placeholder,extras='',end=''){return `<div class="toolbar"><div class="input-wrap">${icon('search')}<input aria-label="${placeholder}" placeholder="${placeholder}" value="${e(state.q)}" data-input="filter"></div>${extras}<span class="spacer"></span>${end}</div>`;}
function filteredItems(){return currentItems().filter(x=>(state.supplier==='all'||(Array.isArray(state.supplier)?state.supplier.includes(x.supplierId):x.supplierId===state.supplier))&&(state.area==='all'||(Array.isArray(state.area)?state.area.includes(x.areaName):x.areaName===state.area))&&(!state.q||norm([x.name,x.internalName,x.sku,x.supplierName,x.areaName].join(' ')).includes(norm(state.q))));}
function inventory(){if(state.tab==='history')return inventoryCountHistory();const rows=filteredItems(),areas=[...new Set(currentItems().map(x=>x.areaName).filter(Boolean))].sort();return heading("Inventory & organization","Inventory","Every item, in the right location and storage area.",btn("Export",'export-inventory','download')+btn("New count",'new-count','clipboard-list','primary'))+`<section class="panel" style="margin-bottom:20px">${tabs([['all','Inventory'],['history','History']])}</section>`+`<section class="panel">${searchToolbar("Search item, SKU, or storage area",`${inventorySupplierPicker.trigger()}${inventoryAreaPicker.trigger()}`,`<span class="table-count">${rows.length} assignments</span>`)}<div id="filtered-content">${inventoryRows(rows)}</div></section>`;}
function inventoryCountHistory(){const rows=historyRows(data.inventoryHistory?.sessions,local.counts,state.store),per=25,page=Math.min(state.page,Math.max(1,Math.ceil(rows.length/per)));return heading("Inventory & organization","Inventory","Completed inventory counts.",btn("New count",'new-count','clipboard-list','primary'))+`<section class="panel">${tabs([['all','Inventory'],['history','History']])}<div class="panel-head"><h2>Count history</h2><span class="table-count">${rows.length} counts</span></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>DATE / TIME</th><th>LOCATION</th><th>EMPLOYEE NAME</th><th aria-label="Details"></th></tr></thead><tbody>${rows.slice((page-1)*per,page*per).map(x=>{const at=historyDateTime(x);return `<tr><td>${e(at.date)}<small>${e(at.time)}</small></td><td>${e(locationName(x.locationId))}</td><td>${e(x.employeeName||'Not recorded')}</td><td><button class="row-action" data-action="count-history-detail" data-id="${e(x.id)}" data-location="${e(x.locationId)}" aria-label="View count ${e(at.date)} ${e(at.time)}">${icon('arrow-up-right')}</button></td></tr>`;}).join('')}</tbody></table></div><div class="pagination"><span>${(page-1)*per+1}–${Math.min(page*per,rows.length)} of ${rows.length}</span><div class="pages">${btn('Previous','page-prev','chevron-left','',page<=1?'disabled':'')}<span class="btn current">${page}</span>${btn('Next','page-next','chevron-right','',page*per>=rows.length?'disabled':'')}</div></div>`:empty('No inventory counts yet','Completed counts for the selected location will appear here.')}</section>`;}

async function showCountHistory(id,location,savedDetail=null){
 let record=savedDetail?.record||historyRows(data.inventoryHistory?.sessions,local.counts).find(x=>x.id===id&&x.locationId===location);if(!record)return;
 if(!Array.isArray(record.lines)){await refreshData();record=historyRows(data.inventoryHistory?.sessions,local.counts).find(x=>x.id===id&&x.locationId===location);if(!record||!Array.isArray(record.lines)){toast('Count items could not be loaded. Refresh the preview server and try again.','circle-alert');return;}}
 const at=historyDateTime(record);let countNotes=record.notes||'',countIssues=record.issues||[],notesUnavailable=false;
 if(savedDetail){countNotes=savedDetail.notes;countIssues=savedDetail.issues;notesUnavailable=savedDetail.notesUnavailable;}
 else if(record.source==='observations'){try{const extra=await api(`/api/inventory/count-notes?id=${encodeURIComponent(id)}&location=${encodeURIComponent(location)}`);countNotes=extra.notes||'';countIssues=extra.issues||[];}catch{notesUnavailable=true;}}

 const itemFor=id=>(data.ingredientItems||[]).find(x=>x.id===id)||(data.items||[]).find(x=>x.id===id);
 const lines=(record.lines||[]).flatMap(line=>line.entries?.length?line.entries.map(entry=>({...line,entryId:entry.id,qty:entry.quantity,uom:entry.uom,itemUnitId:entry.inventoryItemUnitId})): [line]);
 countEditContext={id,location,source:record.source,lines,detail:{record,notes:countNotes,issues:countIssues,notesUnavailable}};countDetailAreaPicker.close(false);countDetailFilter={areas:'all',options:[...new Set(countDetailRows(lines,inventoryItems(),location).map(row=>row.displayArea))].sort((a,b)=>a.localeCompare(b)).map(name=>({id:name,name})),render:()=>{}};
 openModal(`Inventory count details <span class="status ${record.status==='cancelled'?'red':record.status==='draft'?'amber':'green'}">${({draft:'Rascunho',completed:'Concluído',cancelled:'Cancelado'})[record.status||'completed']||'Concluído'}</span>`,`<div class="detail-grid">${pair('Location',e(locationName(location)))}${pair('Employee Name',e(record.employeeName||'Not recorded'))}${pair('Date',e(at.date))}${pair('Time',e(at.time))}</div><div class="count-detail-toolbar"><div class="input-wrap">${icon('search')}<input id="count-detail-search" aria-label="Search count items" placeholder="Search item or SKU"></div><div id="count-detail-area-filter">${countDetailAreaPicker.trigger()}</div></div>${record.source==='observations'?'<p class="muted">Some counts were saved without a storage area. Their recorded quantities are shown as unassigned, not as quantities for a specific area.</p>':''}<div id="count-detail-items"></div><section class="count-detail-notes"><h3>Notes</h3><p>${e(notesUnavailable?'Notes could not be loaded.':countNotes||'No notes recorded.')}</p><h3>Issues</h3>${notesUnavailable?'<p>Issues could not be loaded.</p>':countIssues.length?countIssues.map(issue=>`<div class="count-detail-issue"><strong>${e(itemFor(issue.itemId)?.name||issue.itemId)}</strong><p>${e(issue.text)}</p></div>`).join(''):'<p>No issues reported.</p>'}${notesUnavailable?btn('Retry','count-history-detail','refresh-cw','',`data-id="${e(id)}" data-location="${e(location)}"`):''}</section>`,btn('Close','close'),{wide:true,className:'count-history-detail'});
 const renderItems=()=>{const rows=countDetailRows(lines,inventoryItems(),location,$('#count-detail-search').value).filter(row=>countDetailFilter.areas==='all'||countDetailFilter.areas.includes(row.displayArea));$('#count-detail-items').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>ITEM / SKU</th><th>STORAGE AREA</th><th>QTY.</th><th>UOM</th></tr></thead><tbody>${rows.map(line=>{const item=itemFor(line.itemId),unit=item?.units?.find(u=>(u.itemUnitId||u.id)===line.itemUnitId),quantity=line.qty??line.baseQty,catalogItem=inventoryItems().find(x=>x.id===line.itemId&&x.locationId===location),description=catalogItem?countProductDescription(catalogItem):'';return `<tr><td><strong>${e(catalogItem?.internalName||line.displayName)}</strong><small>${e([line.sku?'SKU '+line.sku:'',description].filter(Boolean).join(' · '))}</small>${line.notes?`<small style="white-space:pre-wrap">${e(line.notes)}</small>`:''}</td><td>${e(line.displayArea)}</td><td>${quantity==null?'Not recorded':preciseNumber(Number(quantity))}</td><td><div class="count-uom-edit"><span>${e(line.uom||unit?.name||line.baseUom||'Not recorded')}</span>${['owner','admin','manager','chef'].includes(session?.role)&&!record.awaitingRefresh&&line.id?btn('','count-edit','pencil','icon-btn',`data-id="${e(line.entryId||line.id)}" aria-label="Edit quantity and UOM for ${e(line.displayName)}"`):''}</div></td></tr>`;}).join('')}</tbody></table></div>`:empty('No items found','Try another item name or SKU.');};
 countDetailFilter.render=()=>{renderItems();icons();};$('#count-detail-search').addEventListener('input',()=>{renderItems();icons();});renderItems();icons();

}

function editCountLine(el){
 if(countEditDraft?.saving)return;
 const line=countEditContext?.lines.find(x=>(x.entryId||x.id)===el.dataset.id);if(!line)return;
 const item=(data.ingredientItems||[]).find(x=>x.id===line.itemId)||inventoryItems().find(x=>x.id===line.itemId);
 const units=prioritizeUnits((item?.units||[]).filter(validUnit));if(!units.length){toast('No valid units available for this item.','circle-alert');return;}
 const source=countEditContext.source==='observations'?'observations':line.entryId?'legacy_entry':'legacy_line';
 const selected=units.find(u=>(u.itemUnitId||u.id)===line.itemUnitId)||units.find(u=>Number(u.factor)===1)||units[0];
 cancelCountLine();
 countEditDraft={...countEditContext,units,line,source,rowId:line.entryId||line.id,oldQuantity:line.qty??line.baseQty,oldUnit:line.itemUnitId||null};
 const quantity=source==='legacy_line'?Number(line.baseQty)/Number(selected.factor):line.qty;
 countDetailAreaPicker.close(false);
 const row=el.closest('tr'),cells=row.querySelectorAll('td');row.classList.add('count-inline-editing');
 countEditDraft.row=row;countEditDraft.originalCells=[cells[2].innerHTML,cells[3].innerHTML];
 cells[2].innerHTML=`<input id="count-edit-qty" class="count-inline-qty" aria-label="QTY." type="number" min="0" max="100000000" step="any" required value="${e(quantity)}">`;
 cells[3].innerHTML=`<div class="count-inline-editor"><select id="count-edit-uom" aria-label="UOM">${units.map(u=>`<option value="${e(u.itemUnitId||u.id)}" ${u===selected?'selected':''}>${e(u.name)}</option>`).join('')}</select><div class="count-inline-actions">${btn('','count-edit-save','check','icon-btn count-inline-save','aria-label="Save" title="Save"')}${btn('','count-edit-cancel','ban','icon-btn','aria-label="Cancel" title="Cancel"')}</div><p id="count-edit-error" class="error-text" role="alert"></p></div>`;
 icons();$('#count-edit-qty').focus();
}
function cancelCountLine(){
 if(countEditDraft?.saving)return;
 const draft=countEditDraft;
 if(draft?.row?.isConnected&&draft.originalCells){draft.row.classList.remove('count-inline-editing');const cells=draft.row.querySelectorAll('td');cells[2].innerHTML=draft.originalCells[0];cells[3].innerHTML=draft.originalCells[1];cells[3].querySelectorAll('[data-action="count-edit"]').forEach(button=>button.disabled=false);icons();}

}
async function saveCountLine(){
 if(!$('#count-edit-qty')?.reportValidity())return;
 const draft=countEditDraft,quantity=Number($('#count-edit-qty').value),unitId=$('#count-edit-uom').value;
 if(draft.saving)return;draft.saving=true;
 const controls=[...draft.row.querySelectorAll('input,select,button')];controls.forEach(control=>control.disabled=true);
 try{await api('/api/inventory/count-edit',{source:draft.source,id:draft.rowId,quantity,unit:unitId,oldQuantity:draft.oldQuantity,oldUnit:draft.oldUnit});}
 catch(error){draft.saving=false;controls.forEach(control=>control.disabled=false);if($('#count-edit-error'))$('#count-edit-error').textContent=error.message;return;}
 draft.saving=false;
 const unit=draft.units.find(u=>(u.itemUnitId||u.id)===unitId);
 const lines=draft.lines.map(line=>(line.entryId||line.id)===draft.rowId?{...line,entries:undefined,qty:quantity,uom:unit.name,itemUnitId:unitId}: {...line,entries:undefined});
 await showCountHistory(draft.id,draft.location,{...draft.detail,record:{...draft.detail.record,lines,awaitingRefresh:true}});
 toast('Count updated.');
 const detailsWindow=$('#overlay-root .modal');
 try{await refreshData();if($('#overlay-root .modal')===detailsWindow)await showCountHistory(draft.id,draft.location,{...draft.detail,record:historyRows(data.inventoryHistory?.sessions,local.counts).find(x=>x.id===draft.id&&x.locationId===draft.location)||{...draft.detail.record,lines}});}
 catch{toast('Count saved. Refresh to reload the latest inventory data.','circle-alert');}
}

function inventoryRows(rows){const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),preparedSales=expandPreparationSales(data.preparationSales,data.recipes||[]);const per=25,page=Math.min(state.page,Math.max(1,Math.ceil(rows.length/per)));return rows.length?`<div class="table-wrap"><table class="inventory-table"><thead><tr><th class="inventory-photo-column">PHOTO</th><th>ITEM / SKU</th><th>SUPPLIER</th><th>LOCATION / STORAGE AREA</th><th>STOCK</th><th><span class="coverage-heading">LIVE INVENTORY <button type="button" class="icon-btn coverage-info" popovertarget="live-inventory-explanation" aria-label="How live inventory is calculated" title="Estimated location total: last complete count + recorded receipts, production and transfers − average consumption since the count. Calculated at session access time.">${icon('info')}</button></span><div id="live-inventory-explanation" class="coverage-explanation" popover><strong>How live inventory is calculated</strong><p>Last complete physical count + subsequent recorded receipts, production and net transfers − average daily consumption × elapsed days, including partial days.</p><p>Consumption uses the latest available 7 days of sales and recipes. Unmapped items may use depletion between comparable counts, including losses. Actual sales consumption is not subtracted again. Recorded waste is deducted separately; it is excluded from the historical depletion average. Invoices without stock movements are excluded.</p><p>This is an estimate for the whole location, repeated for its storage areas, not a measured area balance. Missing data shows —. Negative estimates are displayed as zero.</p><p>Calculated at session access: ${e(new Date(inventorySessionAt).toLocaleString('en-US',{timeZone:'America/New_York'}))} (New York). Reload to update the calculation time.</p><button type="button" class="btn" popovertarget="live-inventory-explanation" popovertargetaction="hide">Close</button></div></th><th><span class="coverage-heading">EST. DAYS LEFT <button type="button" class="icon-btn coverage-info" popovertarget="coverage-explanation" aria-label="How estimated days left is calculated" title="Uses ingredient consumption from sales and registered recipes for the latest 7 available days at this location. Daily average = weekly consumption ÷ 7. Estimated days left = live inventory ÷ daily average. This uses one week, not an average of multiple weeks.">${icon('info')}</button></span><div id="coverage-explanation" class="coverage-explanation" popover><strong>How estimated days left is calculated</strong><p>We use ingredient consumption from sales and registered recipes for the latest 7 available days at this location.</p><p><b>Daily average</b> = weekly consumption ÷ 7.<br><b>Estimated days left</b> = live inventory ÷ daily average.</p><p>This uses one week, not an average of multiple weeks. Sales reflect the whole location, not individual storage areas. Partial calculations are labeled.</p><p>Preview: items without calculated sales usage may use two comparable counts plus recorded receipts, production and transfers. Daily depletion = (opening stock + net receipts − closing stock) ÷ elapsed days. This assumes movements are fully recorded and includes losses. Invoices without stock movements are excluded.</p><button type="button" class="btn" popovertarget="coverage-explanation" popovertargetaction="hide">Close</button></div></th><th></th></tr></thead><tbody>${rows.slice((page-1)*per,page*per).map(x=>{const stock=stockWithProduction(x,local,data.inventoryCounts,data.inventoryHistory?.movements);const live=liveInventory(x,data.inventoryHistory,x.type==='prepared'?preparedSales:data.purchasingSales,data.salesPeriods?.batches||[],inventorySessionAt),coverage=live.qty==null?{days:null,reason:live.reason}:live.daily>0?{...live,days:live.qty/live.daily}:{days:null,reason:'No consumption in this period'};return `<tr><td class="inventory-photo-column">${itemPhotoThumbnail(x,local.itemPhotos[x.id])}</td><td class="item-name"><button class="table-name-button" data-action="item" data-id="${x.rowId}">${e(x.internalName||x.name)}</button><small>${countConversion(x)}</small><small>${e([x.sku?'SKU '+x.sku:'No SKU',countProductDescription(x)].filter(Boolean).join(' · '))}</small></td><td>${e(x.supplierName||"Prep")}</td><td>${e(x.locationName)}<small>${e(x.areaName||"No storage area")}</small></td><td>${stock.qty==null&&stock.knownSubtotal==null?"<span class=\"status\">No count</span>":`<strong>${countQuantity(stock)}</strong><small>${stock.partial?(stock.mixedDates?"Counts from different dates":"Partial count"):stock.addedProduction?`Includes +${preciseNumber(stock.addedProduction)} ${e(stock.uom)} from recorded production`:stock.local?"Local count":e(countDate(stock))}</small>`}</td><td><strong>${live.qty==null?'—':`${live.qty.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})} ${e(live.uom)}`}</strong><small>${live.qty==null?e(live.reason):`Location total · ${live.basis==='inventory'?'Inventory-based':'Sales-based'}${live.partial?' · partial':''}`}</small></td><td title="${e(coverage.days==null?coverage.reason:coverage.basis==='inventory'?`Based on recorded counts and stock receipts/transfers, ${usDate(coverage.start)}–${usDate(coverage.end)}. Includes unrecorded losses; assumes movement history is complete.`:`Live inventory ÷ weekly store consumption × 7 days, ${usDate(coverage.start)}–${usDate(coverage.end)}. Sales are not allocated by storage area.`)}"><strong>${coverage.days==null?'—':`${coverage.days>0&&coverage.days<0.1?'&lt;0.1':coverage.days.toFixed(1)} days`}</strong><small>${coverage.days==null?e(coverage.reason):coverage.basis==='inventory'?'Inventory-based':coverage.partial?'Weekly usage · partial':'Weekly usage'}</small></td><td><button class="row-action" aria-label="Ver ${e(x.name)}" data-action="item" data-id="${x.rowId}">${icon('arrow-up-right')}</button></td></tr>`;}).join('')}</tbody></table></div><div class="pagination"><span>${(page-1)*per+1}–${Math.min(page*per,rows.length)} of ${rows.length}</span><div class="pages">${btn("Previous",'page-prev','chevron-left','',page<=1?'disabled':'')}<span class="btn current">${page}</span>${btn("Next",'page-next','chevron-right','',page*per>=rows.length?'disabled':'')}</div></div>`:empty("No items found","Try a different name, SKU, or filter.");}
function orderTable(rows,deliverySort=null){return rows.length?`<div class="table-wrap"><table><thead><tr><th>SUPPLIER / ORDER</th><th>LOCATION</th><th ${deliverySort?'aria-sort="'+(deliverySort==='asc'?'ascending':'descending')+'"':''}>${deliverySort?`<button class="invoice-sort" data-action="purchase-delivery-sort" aria-label="Sort by delivery, ${deliverySort==='asc'?'newest first':'oldest first'}">DELIVERY ${icon(deliverySort==='asc'?'arrow-down-a-z':'arrow-up-z-a')}</button>`:'DELIVERY'}</th><th>ORDER STATUS</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><div class="name-cell"><span class="supplier-logo">${e(initial(x.supplierName))}</span><div><strong>${e(x.supplierName)}${localMark(x)}</strong><small>${e(shortId(x))} · ${x.lineCount||x.lines?.length||0} ${Number(x.lineCount||x.lines?.length)===1?'item':"items"}</small></div></div></td><td>${e(x.locationName)}</td><td class="mono">${x.expectedAt?usDate(x.expectedAt):'Not set'}</td><td>${status(x.status,x.statusLabel)}${x.receiptEvidence?`<small>${e(({confirmed_received:"Quantities received",fully_received:"Quantities received",partially_received:"Partial receipt",receipt_recorded:"Receipt recorded",no_receipt_recorded:"No linked receiving record"})[x.receiptEvidence.computedStatus]||'')}</small>`:''}</td><td><button class="row-action" aria-label="Order details ${e(shortId(x))}" data-action="order" data-id="${x.id}">${icon('arrow-up-right')}</button></td></tr>`).join('')}</tbody></table></div>`:empty("No orders match this filter","Create an order to plan your next delivery.",btn("Create order",'new-order','plus'));}
function purchases(){return purchasingUI.page();}
function tabs(values){return `<div class="tabs">${values.map(([k,label])=>`<button class="tab ${state.tab===k?'active':''}" data-action="tab" data-value="${k}">${label}</button>`).join('')}</div>`;}
function invoices(){const all=records('invoices').concat(invoiceIntakeUI.drafts()).filter(storeMatch).map(x=>({...x,dbStatus:x.dbStatus??x.status,status:financialStatus(x)})),rows=filterInvoices(all,{...invoiceFilters,query:state.q}).sort((a,b)=>compareInvoices(a,b,invoiceView.sort,invoiceView.direction));const per=invoiceView.per==='all'?Math.max(1,rows.length):invoiceView.per,pages=Math.max(1,Math.ceil(rows.length/per));state.page=Math.min(state.page,pages);const pageRows=rows.slice((state.page-1)*per,state.page*per),unpaid=rows.filter(x=>x.status==='unpaid'),overdue=rows.filter(x=>x.status==='overdue');const summary=(name,items)=>`<article class="invoice-summary panel"><h2>${name==='Total'?'<button type="button" class="invoice-summary-filter" data-action="invoice-clear-filters" aria-label="Total — clear all invoice filters">Total</button>':`<button type="button" class="invoice-summary-filter" data-action="invoice-summary-filter" data-status="${name.toLowerCase()}" aria-pressed="${Array.isArray(invoiceFilters.status)&&invoiceFilters.status.length===1&&invoiceFilters.status[0]===name.toLowerCase()}">${name}</button>`}</h2><div><section><span>Qty</span><strong>${items.length}</strong></section><section><span>Total</span><strong>${money(sum(items,'total'))}</strong></section></div></article>`;const dateHeader=(key,label)=>`<th aria-sort="${invoiceView.sort===key?(invoiceView.direction==='asc'?'ascending':'descending'):'none'}"><button class="invoice-sort" data-action="invoice-sort" data-key="${key}" aria-label="Sort by ${label}, ${invoiceView.sort===key&&invoiceView.direction==='asc'?'newest first':'oldest first'}">${label} ${icon(invoiceView.sort===key?(invoiceView.direction==='asc'?'arrow-down-a-z':'arrow-up-z-a'):'arrow-down-up')}</button></th>`;return heading("Finance & documents",'Invoices',"Approval, payment, and receiving are tracked separately.",btn("Upload invoice",'new-invoice','upload','primary'))+`<div class="invoice-summary-grid">${summary('Unpaid',unpaid)}${summary('Overdue',overdue)}${summary('Total',rows)}</div><div class="prep-filters invoice-filters"><div class="input-wrap invoice-search">${icon('search')}<input aria-label="Search invoice or supplier" placeholder="Search invoice or supplier" value="${e(state.q)}" data-input="filter"></div><button class="hd-date-trigger" data-action="invoice-date-filter" aria-label="Filter by invoice date" aria-haspopup="dialog" aria-expanded="false">${dateTriggerContent(invoiceFilters.start,invoiceFilters.end)}</button>${invoiceSupplierPicker.trigger()}${invoiceStatusPicker.trigger()}${btn('Clear filters','invoice-clear-filters')}</div><section class="panel"><div class="toolbar"><span class="spacer"></span><label class="purchasing-page-size">Items per page<select data-invoice-page-size>${[25,50,100,'all'].map(v=>`<option value="${v}" ${invoiceView.per===v?'selected':''}>${v==='all'?'All':v}</option>`).join('')}</select></label></div><div class="table-wrap"><table><thead><tr><th>INVOICE / SUPPLIER</th><th>LOCATION</th>${dateHeader('date','INVOICE DATE')}${dateHeader('dueDate','DUE DATE')}<th>TOTAL</th><th>STATUS</th><th></th></tr></thead><tbody>${pageRows.map(x=>`<tr><td><button class="table-name-button" data-action="${x.analysisJob?'llm-open-job':'invoice'}" data-id="${x.jobId||x.id}" ${x.analysisJob&&x.analysisStatus!=='draft'?'disabled':''}>#${e(x.number)}</button>${localMark(x)}<small>${e(x.supplierName)}</small></td><td>${e(x.locationName)}</td><td>${usDate(x.date)}</td><td>${usDate(x.dueDate)}</td><td class="mono">${money(x.total)}</td><td>${status(x.status)}${x.analysisJob&&x.analysisStatus==='processing'?'<small>Analyzing…</small>':''}${x.analysisJob&&x.analysisStatus==='failed'?`<small class="error-text">${e(x.error||'Analysis failed. Upload the invoice again.')}</small>`:''}</td><td><button class="row-action" data-action="${x.analysisJob?(x.analysisStatus==='failed'?'llm-dismiss-job':'llm-open-job'):'invoice'}" data-id="${x.jobId||x.id}" ${x.analysisJob&&x.analysisStatus==='processing'?'disabled':''} aria-label="${x.analysisStatus==='failed'?'Dismiss analysis':'Open invoice'} ${e(x.number)}">${icon(x.analysisStatus==='failed'?'x':'arrow-up-right')}</button></td></tr>`).join('')}</tbody></table></div>${rows.length?'':empty("No documents match this filter","Change your search or upload a document to the preview.")}<div class="pagination"><span>${rows.length?(state.page-1)*per+1:0}–${Math.min(state.page*per,rows.length)} of ${rows.length} invoices</span><div class="pages">${btn("Previous",'page-prev','chevron-left','',state.page===1?'disabled':'')}<span class="btn current" aria-current="page">${state.page}</span>${btn("Next",'page-next','chevron-right','',state.page===pages?'disabled':'')}</div></div><div class="snapshot-footer">Documents are uploaded to private storage and verified before confirmation.</div></section>`;}
function transfers(){const rows=records('transfers').filter(x=>(state.store==='all'||[x.toLocationId,x.fromLocationId].includes(state.store))&&norm([shortId(x),x.fromLocationName,x.toLocationName].join(' ')).includes(norm(state.q)));return heading("Between locations","Transfers","From request to receipt, with a record of every step.",btn("New transfer",'new-transfer','plus','primary'))+`<div class="filter-chips"><span class="validation-tag">${icon('route')}Sherwood Plaza → Natick Mall</span><span class="validation-tag">Tuesday: Wed–Fri</span><span class="validation-tag">Friday: Sat–Tue</span></div><div class="board">${[["Requested & approved",['draft','submitted','approved']],["In transit",['dispatched','in_progress']],["Completed",['completed','closed_partial','cancelled','rejected']]].map(([title,sts])=>`<section class="board-column"><div class="column-title">${title}<b>${rows.filter(x=>sts.includes(x.status)).length}</b></div>${rows.filter(x=>sts.includes(x.status)).map(x=>`<article class="task-card" tabindex="0" role="button" data-action="transfer" data-id="${x.id}"><small>${e(shortId(x))}${localMark(x)}${x.kind==='internal_request'?" · Internal request":''}</small><h3>${e(x.fromLocationName)}</h3><p>${icon('arrow-right')} ${e(x.toLocationName)}</p><div class="progress-track"><span style="width:${x.status==='completed'?100:x.status==='dispatched'?70:x.status==='approved'?40:15}%"></span></div><footer><small>${date(x.date)} · ${x.lineCount||x.lines?.length||0} ${Number(x.lineCount||x.lines?.length)===1?'item':"items"}</small>${status(x.status)}</footer></article>`).join('')||"<div class=\"empty\"><p>No transfers at this stage.</p></div>"}</section>`).join('')}</div>`;}
function preparation(){return preparationUI.page();}
function suppliers(){if(supplierUI.selected)return supplierUI.table();const rows=data.suppliers.filter(x=>norm(x.name).includes(norm(state.q))).sort(alphabetical);return heading("Partners","Suppliers","Manage supplier catalogs, purchasing units, and details.",btn("Add supplier",'supplier-create','plus','primary')+btn("Export catalog",'export-inventory','download'))+searchToolbar("Search supplier",'',`<span class="table-count">${rows.length} ${rows.length===1?'supplier':'suppliers'}</span>`)+`<div class="supplier-grid" style="margin-top:20px">${rows.map(x=>{const itemsCount=data.supplierCatalog?supplierUI.count(x.id):unique(currentItems().filter(i=>i.supplierId===x.id)).length;return `<article class="supplier-card" role="button" tabindex="0" data-action="supplier" data-id="${x.id}"><div class="supplier-card-head"><span class="supplier-logo">${e(initial(x.name))}</span>${status(x.active?'active':'inactive')}</div><h3>${e(x.name)}</h3><p>${x.name==='US Foods'?"Minimum order: 25 cases":"Catalog and purchasing units"}</p><div class="supplier-card-footer"><span>${itemsCount} active items</span><span>View catalog ${icon('arrow-up-right')}</span></div></article>`;}).join('')}</div>`;}
