let recipeLayout="grid";
function recipes(){const rows=recipeRows();return heading("Recipe cards","Recipes & modifiers","Versions, yields, and menu mappings in one place.",`<div class="recipe-layout-switch" role="group" aria-label="Recipe view">${btn('Blocks','recipe-layout','layout-grid',recipeLayout==='grid'?'current':'','data-layout="grid" aria-pressed="'+(recipeLayout==='grid')+'"')}${btn('List','recipe-layout','list',recipeLayout==='list'?'current':'','data-layout="list" aria-pressed="'+(recipeLayout==='list')+'"')}</div>`+btn("Export",'export-recipes','download'))+`<section class="panel" style="margin-bottom:20px">${tabs([['all',"All"],['menu','Dish Recipes'],['prep',"Prep items"],['modifier','Modifiers'],['draft',"Drafts"]])}${searchToolbar("Search recipes",'',`<span class="table-count">${rows.length} ${rows.length===1?'recipe':'recipes'}</span>`)}</section><div class="recipe-grid ${recipeLayout==='list'?'recipe-list':''}">${rows.slice(0,60).map(x=>`<article class="recipe-card" tabindex="0" role="button" data-action="recipe" data-id="${x.id}"><div class="recipe-type">${icon(x.type==='prep'?'cooking-pot':x.type==='modifier'?'sliders-horizontal':'utensils')}${e(({prep:"Prep",menu:'Menu item',modifier:'Modifier'})[x.type]||x.type)}</div><h3>${e(x.name)}</h3><p>${e(x.locationName||"No locations assigned")}</p><div class="recipe-card-bottom">${x.editedLocally?"<span class=\"status amber\">Local edit</span>":status(x.status)}<span class="muted" style="font-size:10px">Version ${x.version||'—'} ${icon('arrow-up-right')}</span></div></article>`).join('')}</div>${rows.length>60?notice(`Showing 60 of ${rows.length} recipes. Use search or filters to find a recipe.`,true):''}${rows.length?'':empty("No recipes found","Try a different name or category.")}`;}
function sales(){const p=selectedSalesPeriod();return heading("Operational insights","Sales & usage","Imported Square sales and ingredient usage mapping quality.",periodControl()+btn("Export",'export-sales','download'))+periodNotice(p)+`<section class="panel" style="margin-bottom:20px">${tabs([['all',"Sales overview"],['issues',"Usage issues"]])}</section>`+(state.tab==='issues'?issuesView():`<div class="stats">${stat("Net sales",money(p.total),'dollar-sign',"vs. previous period",p.growth)}${stat("Items sold",number(p.quantity),'shopping-basket',state.dateRange?"In the selected date range":`${p.dates.length} imported days`)}${stat("Gross sales",money(sum(p.current,'grossSales')),'chart-column',"Before discounts")}${stat("Discounts",money(sum(p.current,'discounts')),'badge-percent',"In the selected date range")}</div><div class="dashboard-grid">${salesChart()}<section class="panel"><div class="panel-head"><div><h2>Sales by location</h2><p>Net sales in this date range</p></div></div><div class="report-bars">${data.locations.filter(x=>state.store==='all'||x.id===state.store).map(l=>{const v=sum(p.current.filter(x=>x.locationId===l.id),'netSales');return `<div class="report-bar-row"><span>${e(l.name)}</span><div class="report-bar-track"><span style="width:${p.total?v/p.total*100:0}%"></span></div><strong>${money(v)}</strong></div>`;}).join('')}</div><div style="padding:0 23px 23px" class="muted">${notice("Theoretical usage depends on recipe and modifier mappings. Unresolved sales lines need review.",true)}</div></section></div><section class="panel"><div class="panel-head"><h2>Daily breakdown</h2><span class="table-count">${p.current.length} registros</span></div><div class="table-wrap"><table><thead><tr><th>DATE</th><th>LOCATION</th><th>QUANTITY</th><th>GROSS SALES</th><th>DISCOUNTS</th><th>NET SALES</th></tr></thead><tbody>${[...p.current].sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<tr><td>${date(x.date)}</td><td>${e(x.locationName)}</td><td>${number(x.quantity)}</td><td>${money(x.grossSales)}</td><td>${money(x.discounts)}</td><td><strong>${money(x.netSales)}</strong></td></tr>`).join('')}</tbody></table></div></section>`);}
function issuesView(){if(data.meta.preparationSalesStatus==='loading')return notice("Checking sales issues. You can keep using the app; this screen will update automatically.",true);if(data.meta.preparationSalesStatus==='error')return notice("Unable to check sales issues right now. We’ll try again automatically.",true);const rows=data.issues.filter(storeMatch);return notice(`<strong>${data.meta.pendingImportRows??"Calculating…"} distinct sales lines need review across both locations.</strong> A line can have more than one issue. Do not add these counts together as distinct sales.`)+`<section class="panel"><div class="panel-head"><div><h2>Mapping review</h2><p>Correct catalog mappings before recalculating usage</p></div></div><div class="table-wrap"><table><thead><tr><th>ISSUE</th><th>LOCATION</th><th>OCCURRENCES</th><th></th></tr></thead><tbody>${rows.map((x,i)=>`<tr><td><strong>${e(x.label)}</strong><small>${e(x.code)}</small></td><td>${e(x.locationName)}</td><td>${x.count}</td><td>${btn("View details",'issue','arrow-up-right','sm',`data-id="${data.issues.indexOf(x)}"`)}</td></tr>`).join('')}</tbody></table></div></section>`;}
