async function saveCount(){
  if(!$('#count-form').reportValidity())return;
  const loc=$('#count-location').value;let lines;
  try{lines=Object.entries(dialog.quantities).filter(([,v])=>v!=='').map(([id,v])=>{
    const item=inventoryItems().find(x=>x.rowId===id);if(item?.locationId!==loc)return null;
    const unit=countInputUnit(item);return countEntry(item,v,unit?.itemUnitId||unit?.id);
  }).filter(Boolean);if(!lines.length)throw Error('Enter at least one count.');}
  catch(error){$('#form-error').textContent=error.message;return;}
  const completedAt=new Date(),completedDate=[completedAt.getFullYear(),String(completedAt.getMonth()+1).padStart(2,'0'),String(completedAt.getDate()).padStart(2,'0')].join('-');
  local.counts.push({id:crypto.randomUUID(),locationId:loc,employeeName:$('#count-employee').value.trim(),date:completedDate,countOffsetMinutes:completedAt.getTimezoneOffset(),countedAt:completedAt.toISOString(),createdAt:completedAt.toISOString(),notes:$('#count-notes').value.trim(),issues:Object.entries(dialog.issues).filter(([,text])=>text.trim()).map(([rowId,text])=>({itemId:inventoryItems().find(x=>x.rowId===rowId).id,text})),lines});
  audit(`Inventory count: ${lines.length} items at ${locationName(loc)}`);
  if(await persist('Inventory count saved.')){state.store=loc;goto('inventory');}
}
