function receiptForm(el){const order=data.orders.find(x=>x.id===el.dataset.id);openModal("Receive order",`<form id="receipt-form"><p>Enter the quantities actually received. Confirming adds stock to the selected area.</p>${order.lines.map(l=>{const areas=inventoryItems().find(i=>i.id===l.itemId&&i.locationId===order.locationId)?.areas.filter(a=>a.locationId===order.locationId)||[];return `<div class="field" data-receipt-line="${l.id}"><label>${e(l.name)} · ${e(l.uom)}</label><input type="number" min="0" step="any" value="0" required><select><option value="">Select area</option>${areas.map(a=>`<option value="${a.id}">${e(a.name)}</option>`).join('')}</select></div>`;}).join('')}<p id="receipt-error" class="error-text"></p></form>`,btn("Cancel",'close')+btn("Confirm receipt",'cloud-receipt-save','','primary'),{wide:true});dialog={kind:'receipt',order,id:crypto.randomUUID()};}
async function saveReceipt(){if(!$('#receipt-form').reportValidity())return;const {order,id}=dialog;const lines=[...document.querySelectorAll('[data-receipt-line]')].map(el=>({lineId:el.dataset.receiptLine,quantity:Number(el.querySelector('input').value),areaId:el.querySelector('select').value})).filter(x=>x.quantity>0);try{await command('batch',{changes:[{action:'receipt',payload:{id,orderId:order.id,receivedAt:new Date().toISOString(),lines}}]},id);await refreshData();closeModal(true);render();showOrder(order.id);}catch(error){$('#receipt-error').textContent=error.message;}}
function transferStep(el){
 const transfer=data.transfers.find(x=>x.id===el.dataset.id),step=el.dataset.step,shipment=transfer.dispatches.find(x=>x.id===el.dataset.shipment);
 const rows=step==='receive'?shipment.lines:transfer.lines,loc=step==='receive'?transfer.toLocationId:transfer.fromLocationId;
 openModal(step==='approve'?"Approve quantities":step==='dispatch'?"Record shipment":"Confirm receipt",`<form id="transfer-step-form"><p>${step==='approve'?"Review approved quantities.":"Enter only the quantities actually moved and the corresponding area."}</p>${rows.map(l=>{const max=step==='receive'?l.quantity-l.receivedQuantity:step==='dispatch'?l.approvedQuantity-l.dispatchedQuantity:l.requestedQuantity;const areas=inventoryItems().find(i=>i.id===l.itemId&&i.locationId===loc)?.areas.filter(a=>a.locationId===loc)||[];return `<div class="field" data-transfer-line="${l.id}"><label>${e(l.name)} · ${e(l.uom)}</label><input type="number" min="0" max="${max}" step="any" value="${Math.max(0,max)}" required>${step==='approve'?'':`<select><option value="">Select area</option>${areas.map(a=>`<option value="${a.id}">${e(a.name)}</option>`).join('')}</select>`}</div>`;}).join('')}<p id="transfer-step-error" class="error-text"></p></form>`,btn("Cancel",'close')+btn("Confirm",'cloud-transfer-save','','primary'),{wide:true});
 dialog={kind:'transfer-step',transfer,step,shipment,commandId:crypto.randomUUID()};
}
async function saveTransferStep(){
 if(!$('#transfer-step-form').reportValidity())return;
 const {transfer,step,shipment,commandId}=dialog;
 const lines=[...document.querySelectorAll('[data-transfer-line]')].map(el=>({[step==='receive'?'transfer_line_id':'request_line_id']:el.dataset.transferLine,quantity:Number(el.querySelector('input').value),...(step!=='approve'?{[step==='receive'?'to_storage_area_id':'from_storage_area_id']:el.querySelector('select').value}:{})})).filter(x=>step==='approve'||x.quantity>0);
 try{await command('batch',{changes:[{action:'transfer_step',payload:{commandId,step,data:{request_id:transfer.id,transfer_id:shipment?.id,lines}}}]},commandId);await refreshData();closeModal(true);render();showTransfer(transfer.id);}catch(error){$('#transfer-step-error').textContent=error.message;}
}
