document.addEventListener('change',ev=>{const el=ev.target;if(reportsUI.changed(el))return;if(invoiceIntakeUI.changed(el))return;if(el.dataset.countUnit){countSectionEdited(el);const item=inventoryItems().find(x=>x.rowId===el.dataset.countUnit),old=countInputUnit(item),unit=item.units.find(u=>(u.itemUnitId||u.id)===el.value);const quantity=convertQuantity(dialog.quantities[item.rowId],old,unit);if(quantity!==null)dialog.quantities[item.rowId]=String(quantity);dialog.units[item.rowId]=el.value;renderCount();return;}if(el.dataset.change==='item-photo'){updateItemPhoto(el);return;}if(el.dataset.change==='recipe-photo'){updateRecipePhoto(el);return;}if(doogyUI.changed(el))return;if(wasteUI.changed(el))return;if(supplierUI.changed(el))return;if(preparationUI.changed(el))return;if(purchasingUI.changed(el))return;if(el.dataset.recipeIndex!=null){updateRecipeField(el);return;}if(el.dataset.line!=null){const l=draftLines[Number(el.dataset.line)];l[el.dataset.prop]=el.value;if(el.dataset.prop==='itemId'){const x=eligibleItems().find(x=>x.id===el.value);l.uom=x?.units.find(u=>dialog==='transfer'?u.stocktake:u.ordering)?.name||'';renderLines();}return;}switch(el.dataset.change){case 'supplier-status':supplierUI.changeStatus(el.value);break;case 'store':state.store=el.value;state.area='all';state.page=1;render();break;case 'period':state.days=Number(el.value);state.dateRange=null;render();break;case 'supplier':state.supplier=el.value;state.page=1;render();break;case 'area':state.area=el.value;state.page=1;render();break;case 'form-options':draftLines=[{itemId:'',qty:1,uom:''}];renderLines();break;case 'count-filter':dialog.specific=null;dialog.quantities={};dialog.units={};countAreas();break;case 'production-item':$('#production-uom').value=preparedItems().find(x=>x.id===el.value)?.stocktakeUom||'';break;case 'invoice-file':{if($('#invoice-document-reviewed'))$('#invoice-document-reviewed').checked=false;const file=el.files[0];if(file&&file.size<=20*1024*1024&&['application/pdf','image/png','image/jpeg','image/webp'].includes(file.type)){invoiceFile=file;$('#upload-name').textContent=file.name;}else{invoiceFile=null;el.value='';toast("Use a PDF or image up to 20 MB.",'circle-alert');}break;}}});
