document.addEventListener('input',ev=>{const el=ev.target;if(el.type==='file')return;if(doogyUI.changed(el))return;if(wasteUI.changed(el))return;if(supplierUI.changed(el))return;if(preparationUI.input(el))return;if(purchasingUI.input(el))return;if(el.dataset.recipeIndex!=null){updateRecipeField(el);return;}if(el.dataset.input==='recipe-item-search'){recipeEditor.query=el.value;renderRecipePicker();return;}if(el.dataset.count){countSectionEdited(el);dialog.quantities[el.dataset.count]=el.value;return;}if(el.dataset.line!=null){draftLines[Number(el.dataset.line)][el.dataset.prop]=el.value;return;}switch(el.dataset.input){case 'global':searchResults(el.value);break;case 'count-search':renderCount();break;case 'filter':{state.q=el.value;state.page=1;clearTimeout(filterTimer);filterTimer=setTimeout(()=>{const start=el.selectionStart;render();const input=$('[data-input="filter"]');input?.focus();input?.setSelectionRange(start,start);},180);break;}}});
document.addEventListener('keydown',ev=>{if(!loginRoutes.includes(state.route)&&(ev.metaKey||ev.ctrlKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();globalSearch();}if(ev.key==='Escape'){closeModal();$('.sidebar')?.classList.remove('open');}if((ev.key==='Enter'||ev.key===' ')&&ev.target.matches('[role="button"][data-action]')){ev.preventDefault();ev.target.click();}if(ev.key==='Tab'&&dialog){const elements=[...$('#overlay-root').querySelectorAll('button:not([disabled]),input:not([disabled]):not([type="hidden"]),select,textarea,a[href],[tabindex="0"]')].filter(x=>x.getClientRects().length);const first=elements[0],last=elements.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last?.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first?.focus();}}});
