let refreshGeneration=0,photoRefresh=null;
function refreshPhotos(){
 if(photoRefresh)return;
 const owner=session;
 photoRefresh=loadCloudPhotos().then(photos=>{if(session!==owner||!data)return;data.photoStorageConnected=true;local.itemPhotos=photos.items;local.recipePhotos=photos.recipes;confirmedLocal=structuredClone(local);if(!dialog&&!supplierUI.dirty&&!preparationUI.dirty&&!purchasingUI.dirty)render();}).catch(()=>{if(session===owner&&data)data.photoStorageConnected=false;}).finally(()=>{photoRefresh=null;});
}
async function refreshData(background=false){
 const generation=++refreshGeneration,owner=session,fresh=await api('/api/data');
 if(owner!==session||generation!==refreshGeneration||(background&&(syncing||dialog||supplierUI.dirty||preparationUI.dirty||purchasingUI.dirty)))return false;
 data=fresh;if(fresh.access?.role)session.role=fresh.access.role;confirmedLocal=structuredClone(local);refreshPhotos();return true;
}
configureCommit(async next=>{
 if(!session||syncing)throw Error("Wait for synchronization to finish before saving.");
 syncing=true;
 try{
  const before=confirmedLocal||loadLocal({getItem:()=>null});
  const changes=[];
  for(const kind of ['orders','transfers','counts','production','invoices'])for(const record of next[kind]||[]){const old=before[kind]?.find(x=>x.id===record.id);if(JSON.stringify(old)!==JSON.stringify(record))changes.push({action:kind,payload:record});}
  for(const [kind,action] of [['supplierItemEdits','catalog'],['recipeEdits','recipe']])for(const [id,value] of Object.entries(next[kind]||{}))if(JSON.stringify(before[kind]?.[id])!==JSON.stringify(value)){changes.push({action,payload:action==='catalog'?{id,shared:next.itemEdits[value.itemId],vendor:value,expectedUpdatedAt:data.supplierCatalog.items.find(x=>x.id===id)?.updatedAt,expectedItemUpdatedAt:data.supplierCatalog.items.find(x=>x.id===id)?.itemUpdatedAt}:{id,...value,expectedVersionId:data.recipes.find(x=>x.id===id)?.versionId}});}
  if(isStaff(session?.role)&&changes.some(change=>change.action!=='counts'))throw Error('Staff can save inventory counts only.');
  if(changes.length)await command('batch',{changes},next.pendingCommandId||(next.pendingCommandId=crypto.randomUUID()));
  const photos={itemPhotos:next.itemPhotos,recipePhotos:next.recipePhotos};
  Object.assign(next,loadLocal({getItem:()=>null}),photos);delete next.pendingCommandId;
  local=next;confirmedLocal=structuredClone(local);try{await refreshData();}catch(error){toast("Saved to the database. Screen refresh pending: "+error.message,'circle-alert');}
 }finally{syncing=false;}
});
createRefreshLoop({canRefresh:()=>!!session&&!!data&&!loginRoutes.includes(state.route)&&!syncing&&!dialog&&!isDatePickerOpen()&&!locationPicker.isOpen&&!inventorySupplierPicker.isOpen&&!inventoryAreaPicker.isOpen&&!invoiceSupplierPicker.isOpen&&!invoiceStatusPicker.isOpen&&!foodCategoryPicker.isOpen&&!foodStatusPicker.isOpen&&!preparationUI.filterOpen&&!purchasingUI.filterOpen&&!isNavigationOpen()&&!document.hidden&&!document.activeElement?.closest('[data-report-filter]')&&!supplierUI.dirty&&!preparationUI.dirty&&!purchasingUI.dirty,refresh:async()=>{if(await refreshData(true))render();},onError:error=>{if(error.status===401||error.status===403){session=null;data=null;render();}else toast("Not refreshed: "+error.message,'circle-alert');}});
